#!/bin/sh
# Writes the generated files of tests/packages (docs/design/testing.md section 5.8): for each
# version of each AI-tier package of tests/packages/ranking.json whose kind is `program`, the
# directory tests/packages/<name>@<major>/ with
# - package.json: one dependency at the exact version, so the directory is a member of the
#   pnpm workspace and pnpm-lock.yaml pins its integrity. A peer dependency that the README
#   of the package installs next to it is a second dependency, from the list `peers` below,
#   so main.mjs imports only what its package.json names;
# - exports.mjs: imports the package and prints each export name with its typeof, sorted;
# - exports.cjs: requires the package and prints the typeof of module.exports, then each
#   key with its typeof, sorted.
# A package whose root entry does not load on Node gets the first subpath that its README or
# its main.mjs imports, from the list `entries` below.
# main.mjs is written by hand from the usage section of the README, so this script leaves it.
#
# Then run `pnpm install`, write main.mjs, and run scripts/freeze-expectations.sh
# tests/packages.
#
# Usage: scripts/package-exports.sh. It needs jq.

set -eu

root=$(cd "$(dirname "$0")/.." && pwd)
packages="$root/tests/packages"

# Lines of `<directory> <peer> <version>`.
peers='
@hono/node-server@1 hono 4.13.13
@hono/node-server@2 hono 4.13.13
@langchain/anthropic@1 @langchain/core 1.2.18
@langchain/langgraph@1 @langchain/core 1.2.18
@langchain/openai@1 @langchain/core 1.2.18
@mastra/core@1 zod 4.6.7
@modelcontextprotocol/sdk@1 zod 4.6.7
@openai/agents@0.11 zod 4.6.7
@openai/agents@0.20 zod 4.6.7
ajv-formats@2 ajv 8.20.0
ajv-formats@3 ajv 8.20.0
express-rate-limit@8 express 5.3.0
langchain@0.3 @langchain/core 0.3.80
langchain@1 @langchain/core 1.2.18
zod-to-json-schema@3 zod 3.25.76
'

# Lines of `<directory> <specifier>`. langchain 0.3 exports no root, and the root of
# @modelcontextprotocol/sdk 1.32.1 names dist/esm/index.js, which the package does not ship.
entries='
@modelcontextprotocol/sdk@1 @modelcontextprotocol/sdk/server/mcp.js
langchain@0.3 langchain/text_splitter
'

jq -r '.packages[] | select(.ai and .kind == "program") | .name as $name
    | .versions[] | "\($name) \(.major) \(.version)"' "$packages/ranking.json" |
    while read -r name major version; do
        directory="$packages/$name@$major"
        mkdir -p "$directory"
        slug=$(printf '%s-%s' "$name" "$major" | sed 's/@//; s#/#-#')
        peer=$(printf '%s\n' "$peers" | awk -v directory="$name@$major" '$1 == directory { print $2, $3 }')
        entry=$(printf '%s\n' "$entries" | awk -v directory="$name@$major" '$1 == directory { print $2 }')
        entry=${entry:-$name}
        jq -n --arg slug "$slug" --arg name "$name" --arg version "$version" --arg peer "$peer" '{
            name: "@bouy/package-\($slug)",
            private: true,
            description: "Generated by scripts/package-exports.sh from tests/packages/ranking.json.",
            dependencies: ({($name): $version} + if $peer == "" then {} else
                ($peer | split(" ") | {(.[0]): .[1]}) end | to_entries | sort_by(.key) | from_entries)
        }' >"$directory/package.json"
        cat >"$directory/exports.mjs" <<EOF
// Generated by scripts/package-exports.sh. Each export of the package, with its type.
import * as namespace from "$entry";

for (const name of Object.keys(namespace).sort()) {
  console.log(\`\${name}: \${typeof namespace[name]}\`);
}
EOF
        cat >"$directory/exports.cjs" <<EOF
// Generated by scripts/package-exports.sh. The type of module.exports, then each of its
// keys, with its type.
const exported = require("$entry");

console.log(\`module.exports: \${typeof exported}\`);
for (const name of Object.keys(exported).sort()) {
  console.log(\`\${name}: \${typeof exported[name]}\`);
}
EOF
        echo "tests/packages/$name@$major: $name $version"
    done
